  clock.now = Instant.parse(deadline);
  service.expire();
  assertThat(service.read(user, id, "result").path("outcome").asText()).isEqualTo("EXPIRED");
  assertThatThrownBy(() -> service.claim(worker, id, "again", claim(id, "worker-1", 2)))
      .hasMessage("EXPIRED");
}

