      .as("a later command on the session answers EXPIRED, not PUBLICATION_CONFLICT")
      .hasMessage("EXPIRED");
  assertThat(teardownReason(id))
      .as("the stop sent to the runner names the same reason (assignmentLifecycle does too)")
      .isEqualTo("EXPIRED");
}

