          org.assertj.core.api.Assertions.catchThrowable(
              () -> routedJdbc.queryForObject("SELECT 1", Integer.class));
      assertThat(routeRefusal).isNotNull();
      assertThat(postgresFailure(routeRefusal).getSQLState()).startsWith("08");
      caller.interrupt();
